import type { MetadataRoute } from "next";
import { SITE } from "@/lib/site";

// Colors match the night theme in app/globals.css (--bg #0e110f). Icons are
// generated by lib/seo/generate-icons.mjs into public/icons/.
export default function manifest(): MetadataRoute.Manifest {
  return {
    id: "/",
    name: SITE.name,
    short_name: "Tombstones",
    description: SITE.description,
    start_url: "/",
    scope: "/",
    display: "standalone",
    background_color: "#0e110f",
    theme_color: "#0e110f",
    categories: ["travel", "education", "entertainment"],
    icons: [
      { src: "/icons/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/icons/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      { src: "/icons/maskable-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
    ],
  };
}
